        subagentStops: {
          count: sanitizeStopCount(storedStops.count, baseStops.count ?? DEFAULT_SUBAGENT_STOPS.count),
          values: sanitizeStopValues(storedStops.values, baseStops.values ?? DEFAULT_SUBAGENT_STOPS.values),
        },
