          fetch(RESTART_ENDPOINT, { method: 'GET', cache: 'no-store' }).then((response) => {
            if (disposed) return;
            setRestartArmed(response.ok === true);
          }, () => {
            if (!disposed) setRestartArmed(false);
          });
